package com.dynasty.blueprint.boss;

import net.minecraft.core.*;
import net.minecraft.core.registries.Registries;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.level.*;
import net.minecraft.world.*;
import net.minecraft.world.entity.MobSpawnType;
import net.minecraft.world.level.*;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.phys.*;
import net.minecraftforge.event.TickEvent;
import net.minecraftforge.event.entity.player.PlayerInteractEvent;
import net.minecraftforge.eventbus.api.SubscribeEvent;
import net.minecraftforge.fml.common.Mod;
import java.util.*;

/** Bounded loaded-chunk platform discovery, exactly capped authored floor loss and post-victory rope. */
@Mod.EventBusSubscriber(modid="dynasty")
public final class StargazerPlatforms {
    public static final int FLOOR_AREA=floorArea(),FLOOR_LOSS_CAP=(int)Math.floor(FLOOR_AREA*.15);
    private static int floorArea(){int count=0;for(int x=-17;x<=17;x++)for(int z=-17;z<=17;z++)if(StargazerPlatformPiece.inside(x,z))count++;return count;}
    public static boolean breakableCell(BlockPos centre,BlockPos at){int x=at.getX()-centre.getX(),z=at.getZ()-centre.getZ();return at.getY()==centre.getY()-1&&StargazerPlatformPiece.inside(x,z)&&Math.abs(x)>2&&Math.abs(z)>2&&Math.abs(Math.abs(x)-Math.abs(z))>1;}
    public static boolean loaded(ServerLevel w,BlockPos centre){return com.dynasty.blueprint.artifact.ArtifactAbility.loaded(w,new AABB(centre).inflate(25,1,25).expandTowards(0,60,0).expandTowards(0,-20,0));}
    public static boolean summon(ServerLevel w,StargazerPlatformState.Platform site){if(w.dimension()!=Level.OVERWORLD||w.getDifficulty()==Difficulty.PEACEFUL||site.defeated||site.boss!=null||!loaded(w,site.centre)||!w.getBlockState(site.centre.below()).is(WoodKiteContent.SOCKET.get()))return false;var at=Vec3.atBottomCenterOf(site.centre).add(22,-16,0);var type=WoodKiteContent.KITE.get();if(!w.noCollision(null,type.getDimensions().makeBoundingBox(at)))return false;var boss=type.create(w);if(boss==null)return false;boss.moveTo(at.x,at.y,at.z,0,0);boss.bindArena(site.centre);boss.finalizeSpawn(w,w.getCurrentDifficultyAt(site.centre),MobSpawnType.EVENT,null,null);if(!w.addFreshEntity(boss))return false;site.boss=boss.getUUID();StargazerPlatformState.get(w).setDirty();return true;}
    @SubscribeEvent public static void click(PlayerInteractEvent.RightClickBlock e){if(e.getHand()!=InteractionHand.MAIN_HAND||!(e.getEntity() instanceof ServerPlayer p)||!(e.getLevel() instanceof ServerLevel w)||p.isSpectator()||p.isCreative()||!p.getMainHandItem().isEmpty()||!w.getBlockState(e.getPos()).is(WoodKiteContent.SOCKET.get())||p.distanceToSqr(Vec3.atCenterOf(e.getPos()))>6.5*6.5)return;var site=StargazerPlatformState.get(w).platforms.get(e.getPos().above().asLong());if(site!=null&&summon(w,site)){p.displayClientMessage(net.minecraft.network.chat.Component.translatable("message.dynasty.stargazer_platform"),false);e.setCanceled(true);e.setCancellationResult(InteractionResult.SUCCESS);}}
    @SubscribeEvent public static void discover(TickEvent.PlayerTickEvent e){if(e.phase!=TickEvent.Phase.END||!(e.player instanceof ServerPlayer p)||p.isSpectator()||!(p.level() instanceof ServerLevel w)||w.dimension()!=Level.OVERWORLD||w.getGameTime()%80!=Math.floorMod(p.getId()+31,80))return;var registry=w.registryAccess().registryOrThrow(Registries.STRUCTURE);var id=new ResourceLocation("dynasty","stargazer_platform");var starts=new LinkedHashSet<net.minecraft.world.level.levelgen.structure.StructureStart>();var origin=p.chunkPosition();int budget=64;
        for(int dx=-1;dx<=1;dx++)for(int dz=-1;dz<=1;dz++){var at=new ChunkPos(origin.x+dx,origin.z+dz);if(!w.hasChunk(at.x,at.z))continue;var c=w.getChunkSource().getChunk(at.x,at.z,net.minecraft.world.level.chunk.ChunkStatus.STRUCTURE_REFERENCES,false);if(c==null)continue;c.getAllStarts().forEach((type,start)->{if(id.equals(registry.getKey(type)))starts.add(start);});for(var refs:c.getAllReferences().entrySet())if(id.equals(registry.getKey(refs.getKey())))for(long packed:refs.getValue()){if(budget--<=0)break;var owner=new ChunkPos(packed);if(w.hasChunk(owner.x,owner.z)){var source=w.getChunkSource().getChunk(owner.x,owner.z,net.minecraft.world.level.chunk.ChunkStatus.STRUCTURE_STARTS,false);if(source!=null){var start=source.getStartForStructure(refs.getKey());if(start!=null)starts.add(start);}}}}
        for(var start:starts)if(start.isValid()&&start.getBoundingBox().isInside(p.blockPosition()))for(var piece:start.getPieces())if(piece instanceof StargazerPlatformPiece platform)StargazerPlatformState.get(w).register(platform.centre());
    }
    public static void scar(WoodKite owner,BlockPos mark){if(!(owner.level() instanceof ServerLevel w)||owner.arenaCentre()==null||!net.minecraftforge.event.ForgeEventFactory.getMobGriefingEvent(w,owner)||!loaded(w,owner.arenaCentre()))return;var state=StargazerPlatformState.get(w);var site=state.platforms.get(owner.arenaCentre().asLong());if(site==null||site.defeated||!owner.getUUID().equals(site.boss))return;int budget=40;for(int r=0;r<=6;r++)for(int dx=-r;dx<=r;dx++)for(int dz=-r;dz<=r;dz++){if(Math.max(Math.abs(dx),Math.abs(dz))!=r||dx*dx+dz*dz>36||budget<=0||site.removed.size()+site.charred.size()>=FLOOR_LOSS_CAP)continue;var at=new BlockPos(mark.getX()+dx,site.centre.getY()-1,mark.getZ()+dz);var block=w.getBlockState(at);if(!breakableCell(site.centre,at)||site.removed.contains(at.asLong())||site.charred.containsKey(at.asLong())||!block.is(WoodKiteContent.PLANK.get())||w.getBlockEntity(at)!=null||!net.minecraftforge.event.ForgeEventFactory.onEntityDestroyBlock(owner,at,block))continue;w.setBlock(at,WoodKiteContent.CHARRED.get().defaultBlockState(),3);site.charred.put(at.asLong(),w.getGameTime()+30);budget--;state.setDirty();}}
    public static void confirmedDeath(WoodKite boss){if(!(boss.level() instanceof ServerLevel w)||boss.arenaCentre()==null)return;var state=StargazerPlatformState.get(w);var site=state.platforms.get(boss.arenaCentre().asLong());if(site==null||site.defeated||!boss.getUUID().equals(site.boss))return;site.defeated=true;site.boss=null;site.victoryAt=w.getGameTime();site.ropeY=site.centre.getY()+1;state.setDirty();int count=0;for(var p:w.players())if(count<16&&p.isAlive()&&!p.isCreative()&&!p.isSpectator()&&p.distanceToSqr(Vec3.atBottomCenterOf(site.centre))<=32*32&&state.firstRewarded.add(p.getUUID())){var page=new net.minecraft.world.item.ItemStack(WoodKiteContent.PAGE.get());if(!p.addItem(page))p.drop(page,false);count++;state.setDirty();}}
    public static void destroyed(WoodKite boss){if(!(boss.level() instanceof ServerLevel w)||boss.arenaCentre()==null)return;var state=StargazerPlatformState.get(w);var site=state.platforms.get(boss.arenaCentre().asLong());if(site!=null&&!site.defeated&&boss.getUUID().equals(site.boss)){site.boss=null;state.setDirty();}}
    @SubscribeEvent public static void environment(TickEvent.LevelTickEvent e){if(e.phase!=TickEvent.Phase.END||!(e.level instanceof ServerLevel w)||w.dimension()!=Level.OVERWORLD||w.getGameTime()%10!=0)return;int sites=2;for(var site:StargazerPlatformState.get(w).platforms.values())if((!site.charred.isEmpty()||site.defeated&&(site.ropeY>w.getMinBuildHeight()||site.victoryAt>=0&&w.getGameTime()-site.victoryAt<1200))&&w.players().stream().anyMatch(p->!p.isSpectator()&&p.position().subtract(Vec3.atBottomCenterOf(site.centre)).multiply(1,0,1).lengthSqr()<48*48)&&loaded(w,site.centre)){collapse(w,site,8);if(site.defeated&&site.victoryAt>=0&&w.getGameTime()-site.victoryAt<1200){for(int i=0;i<4;i++){double a=w.getGameTime()*.025+i*Math.PI/2;w.sendParticles(net.minecraft.core.particles.ParticleTypes.END_ROD,site.centre.getX()+.5+Math.cos(a)*12,site.centre.getY()+12,site.centre.getZ()+.5+Math.sin(a)*12,1,0,0,0,0);}}if(site.defeated&&site.victoryAt>=0&&w.getGameTime()-site.victoryAt>=220)extendRope(w,site,12);if(--sites<=0)break;}}
    public static void collapse(ServerLevel w,StargazerPlatformState.Platform site,int budget){if(!loaded(w,site.centre))return;var it=site.charred.entrySet().iterator();while(it.hasNext()&&budget>0){var e=it.next();long now=w.getGameTime();if(e.getValue()>now&&e.getValue()<=now+30)continue;var at=BlockPos.of(e.getKey());if(w.getBlockState(at).is(WoodKiteContent.CHARRED.get())&&w.getBlockEntity(at)==null)w.setBlock(at,Blocks.AIR.defaultBlockState(),3);site.removed.add(e.getKey());it.remove();budget--;StargazerPlatformState.get(w).setDirty();}}
    public static void extendRope(ServerLevel w,StargazerPlatformState.Platform site,int budget){if(!site.defeated||!loaded(w,site.centre))return;if(site.ropeY>site.centre.getY()+1||site.ropeY<w.getMinBuildHeight())site.ropeY=site.centre.getY()+1;while(budget-->0&&site.ropeY>w.getMinBuildHeight()+1){var at=new BlockPos(site.centre.getX(),site.ropeY,site.centre.getZ());var block=w.getBlockState(at);boolean ownAnchor=at.equals(site.centre.below())&&block.is(WoodKiteContent.SOCKET.get())||at.equals(site.centre.below(2))&&block.is(Blocks.STRIPPED_DARK_OAK_LOG);if(!block.isAir()&&!block.is(WoodKiteContent.ROPE.get())&&!ownAnchor||!w.getFluidState(at).isEmpty()||w.getBlockEntity(at)!=null){site.ropeY=w.getMinBuildHeight();StargazerPlatformState.get(w).setDirty();break;}if(!block.is(WoodKiteContent.ROPE.get()))w.setBlock(at,WoodKiteContent.ROPE.get().defaultBlockState(),3);site.ropeY--;StargazerPlatformState.get(w).setDirty();}}
    @SubscribeEvent public static void tooltips(net.minecraftforge.event.entity.player.ItemTooltipEvent e){var stack=e.getItemStack();if(stack.is(WoodKiteContent.CORE.get()))e.getToolTip().add(net.minecraft.network.chat.Component.translatable("tooltip.dynasty.stargazer_kite_core_mechanism"));else if(stack.is(WoodKiteContent.FEATHER.get()))e.getToolTip().add(net.minecraft.network.chat.Component.translatable("tooltip.dynasty.stargazer_cinnabar_wood_feather"));else if(stack.is(WoodKiteContent.PAGE.get()))e.getToolTip().add(net.minecraft.network.chat.Component.translatable("tooltip.dynasty.luban_clockwork_diagram_page"));}
    private StargazerPlatforms(){}
}
